<?php
namespace AtrioTeam\LaravelDeployment\Console\Commands;

use Illuminate\Console\Command;
use function Laravel\Prompts\select;
use Illuminate\Support\Facades\File;
use Illuminate\Contracts\Console\PromptsForMissingInput;

class SetupCommand extends Command  implements PromptsForMissingInput
{
    // The name and signature of the console command.
    protected $signature = 'deployment:setup {setupType : The type of setup to use}';

    // The console command description.
    protected $description = 'Setup the deployment';

    // Execute the console command.
    public function handle()
    {
        $type = $this->argument('setupType');

        $this->info("Setting up deployment for $type");


        // copy the yml file
        File::ensureDirectoryExists(base_path('.github/workflows'));
        File::copy(
            __DIR__ . '/../../../stubs/.github/workflows/'.$type.'.yml',
            base_path('.github/workflows/deployment.yml')
        );

        // copy the http config and startup_vendor script
        if($type === 'http') {
            File::copy(
                __DIR__ . '/../../../stubs/config/http.php',
                config_path('laravel-deployment.php')
            );
            File::copy(
                __DIR__ . '/../../../stubs/public/startup_vendor.php',
                public_path('startup_vendor.php')
            );

        }


        // copy the ssh deployment script
        File::ensureDirectoryExists(base_path('scripts'));
        if($type === 'ssh') {
            File::copy(
                __DIR__ . '/../../../stubs/scripts/deploy.sh',
                base_path('scripts/deploy.sh')
            );
        }

        $this->info('Deployment setup completed');

    }


    /**
     * Prompt for missing input arguments using the returned questions.
     *
     * @return array<string, string>
     */
    protected function promptForMissingArgumentsUsing(): array
    {
        return [
            'setupType' => fn () => select(
                label: 'Which setup type do you want to use?',
                options: ['http', 'ssh'],
            ),
        ];
    }
}

