<?php

/**
 * create a laravel provider
 */

namespace AtrioTeam\Lintilla;

use AtrioTeam\Lintilla\Console\Commands\LinksExport;
use AtrioTeam\Lintilla\Console\Commands\LinksImport;
use AtrioTeam\Lintilla\Console\Commands\TranslationsExport;
use AtrioTeam\Lintilla\Console\Commands\TranslationsImport;
use AtrioTeam\Lintilla\Localization\LangManager;
use AtrioTeam\Lintilla\Localization\Router;
use Illuminate\Support\Facades\Artisan;

class ServiceProvider extends \Illuminate\Support\ServiceProvider
{
    public function register(): void
    {

        /**
        * Lang manager
        */
        $this->app->singleton(LangManager::class, function ($app) {
            return new LangManager(config("lintilla.locales"), config("lintilla.lang.source"));
        });


        /**
         * Localized routes
         */
        $this->app->singleton(Router::class, function () {
            $router = new Router(config("lintilla.locales"), config("lintilla.lang.source"));
            return $router;
        });


    }

    public function boot(): void
    {
        $this->commands([
            LinksImport::class,
            LinksExport::class,
            TranslationsImport::class,
            TranslationsExport::class,
        ]);

        $this->mergeConfigFrom(__DIR__ . '/../config/lintilla.php', 'lintilla');

        $this->publishesMigrations([
            __DIR__.'/../database/migrations' => database_path('migrations'),
            __DIR__ . '/../lang' => lang_path('vendor/lintilla'),
            __DIR__ . '/../config/lintilla.php' => config_path('lintilla.php'),
        ], 'lintilla-setup');


        /**
         * Views
         */
        $this->loadViewsFrom(__DIR__ . '/../resources/views', 'lintilla');

        /**
         * Publish package views
         */
        $this->publishes([
            __DIR__ . '/../resources/views' => resource_path('views/vendor/lintilla'),
        ], 'lintilla-views');


        /**
         * Routes
         */
        $this->loadRoutesFrom(__DIR__ . '/../routes/web.php');

        /**
         * Autoexport translations and links
         */
        if (config('lintilla.lang.autoexport') === true && !$this->app->runningInConsole()) {
            Artisan::call("lintilla:translations-export");
            Artisan::call("lintilla:links-export");
        }

    }


}

