<?php

/**
 * @author Jacopo Viscuso, Emanuele Fornasier
 **/

namespace App\Html;

use DOMDocument;
use DOMElement;
use DOMXpath;

/**
 * Inserisce codice inline css prendendolo dal tag style di un documento
 **/
class CssInliner
{
    public static function inlineCss(string $htmlMail): string|false
    {

        libxml_use_internal_errors(true) and libxml_clear_errors();

        $thisDocument = new DOMDocument('1.0', 'UTF-8');     // istanzio la classe DOMDocument (serve per trasformare html in oggetto)
        $htmlMail = mb_convert_encoding($htmlMail, 'HTML-ENTITIES', "UTF-8");

        $internalErrors = libxml_use_internal_errors(true);

        $thisDocument->loadHTML($htmlMail);           // faccio il parsing dell'html mail

        libxml_use_internal_errors($internalErrors);

        $thisDocumentXPath = new DOMXpath($thisDocument);   // istanzio la classe DOMXpath (fa il parsing dei tag html)

        $styleTag = $thisDocumentXPath->query('//style');   // recupero il contenuto dei tag style
        $style = '';                                        // stringa con tutte le regole css contenute nei vari tag style
        if ($styleTag) :
            foreach ($styleTag as $s) :
                $style .= $s->nodeValue;
            endforeach;
        endif;


        $style  = trim(preg_replace('/$[\s\r\t\n]+/m', ' ', $style));     // metto tutto in un'unica linea
        $style  = preg_replace('/(\/\*\s*[^\*]*\s*\*\/)/', '', $style); // rimuovo i commenti
        $style  = preg_replace('/\@import[^\)]+\)\;/', '', $style);     // rimuovo eventuali valori importati

        // separo le singole regole
        $arRules = preg_split('/(\})[\s\r\n\t]*/', $style, -1, PREG_SPLIT_NO_EMPTY); // transformo le regole css in array
        $arCssInfo = array();   // array dove ogni elemento avrà come chiave il destinatario della regola e come valore la regola stessa

        if ($arRules) :
            foreach ($arRules as $R) :
                if (preg_match('/\s*\@import/', $R)) : continue;
                endif;        // se trovo un valore import non considero
                $R      = trim(preg_replace('/^[\s\r\t\n]+/m', ' ', $R));     // tolgo gli spazi iniziali
                $arCSS  = preg_split('/\s*\{\s*/', $R);                      // separo tags da regole di stile
                if ($arCSS === false || count($arCSS) < 2) : continue;
                endif;
                $arTags = preg_split('/\s*\,\s*/', $arCSS[0]);               // se le regole coinvolgono più tags li separo
                if ($arTags) :                                                // assegno ad ogni tag la regola
                    foreach ($arTags as $Tag) :
                        $arCssInfo[(string) $Tag] = $arCSS[1];               // eventuali sovrapposizioni le normalizzo in seguito
                    endforeach;
                endif;
            endforeach;
        endif;

        $elementsList = [];

        foreach ($arCssInfo as $cssPath => $cssRule) :    // ciclo tutte le regole css

            $arTags = preg_split('/\s+/', $cssPath);     // creo un array con il percorso dei destinatari della regola
            if ($arTags === false) : continue;
            endif;

            $strTag = '';                               // stringa per effettuare la query di DOMXpath
            foreach ($arTags as $k => $Tag) :
                $Tag = trim($Tag);                      // tolgo eventuali spazi

                // se ci sono pseudo classi non considero tutta la regola
                if (preg_match('/\:/', $Tag)) :
                    continue 2;
                endif;
                $arIdentifiers = preg_split('/(\.|\#)/', $Tag, -1, PREG_SPLIT_DELIM_CAPTURE | PREG_SPLIT_NO_EMPTY);    // verifico se sto cercando tag, classe o id
                if ($arIdentifiers === false) : continue 2;
                endif;

                switch (count($arIdentifiers)): case 3:
                    $tagName    = $arIdentifiers[0];
                    $identifier = $arIdentifiers[1];
                    $attrValue  = $arIdentifiers[2];
                    break;
                case 2:
                    $tagName    = '*';
                    $identifier = $arIdentifiers[0];
                    $attrValue  = $arIdentifiers[1];
                    break;
                default:
                    $tagName    = $arIdentifiers[0];
                    $identifier = '';
                    $attrValue  = '';
                endswitch;

                switch ($identifier):    // compongo la stringa di ricerca
                    case '#':
                        $strTag .= $tagName . '[@id="' . $attrValue . '"]//';
                        break;
                    case '.':
                        $strTag .= $tagName . '[@class="' . $attrValue . '"]//';
                        break;
                    default:
                        $strTag .= $tagName . '//';
                endswitch;
            endforeach;

            // Per saltare il nodo radice, che darebbe errore su $element->getAttribute().
            if ($strTag === './/') {
                continue;
            }


            $result = $thisDocumentXPath->query('//' . substr($strTag, 0, -2));     // recupero l'elemento sulla base della stringa
            if ($result !== false) :                                             // se ho l'elemento (o gli elementi) cercati
                foreach ($result as $element) :
                    if (!$element instanceof DOMElement) : continue;
                    endif;

                    // memorizzo la regola per l'elemento, la applicherò dopo
                    $thisStyle = $element->getAttribute('data-style') . ' ' . $cssRule;
                    $element->setAttribute('data-style', trim($thisStyle));

                    $elementsList[] = $element;

                endforeach;
            endif;

        endforeach;

        // applico tutte le regole ad ogni elemento, inserendo l'eventuale style inline già esistente
        // per ultimo, in modo da sovrascrivere le regole css appena recuperate
        foreach ($elementsList as $key => $element) {
            $thisStyle = $element->getAttribute('data-style');
            $inlineStyle = $element->getAttribute('style');
            $element->setAttribute('style', trim($thisStyle . ' ' . $inlineStyle));
            $element->removeAttribute('data-style');
        }

        $htmlMail = $thisDocument->saveHTML();// ricompongo l'html

        return $htmlMail;

    }

}

