<?php

namespace App\View\Components;

use Exception;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
use Illuminate\View\Component;

/**
 * Render di un immagine responsive
 * basandosi sulle impostazioni del cms
 */
class ResponsiveImage extends Component
{
    public mixed $image;

    public string $tag;

    /** @var string|null */
    public $config;

    public static bool $disableLazyload = false;

    /** @var array<string, mixed> */
    public array $extraAttributes;

    public bool $lazy;

    public string $configKey;

    /**
     * Create a new component instance.
     *
     * @param mixed $image istanza del file caricato come da metodo loadFile di CommonTrait
     * @param array<string, mixed> $extraAttributes attributi extra per il tag (es. sizes)
     * @param string $tag img|picture
     * @param string|null $config chiave configuarazione per il file come da cms (codice funzione)
     * @param bool $lazy se true attiva lazyload
     * @return void
     */
    public function __construct(mixed $image = null, array $extraAttributes = [], string $tag = 'img', ?string $config = null, bool $lazy = false)
    {
        $this->image = $image;
        $this->extraAttributes = $extraAttributes;
        $this->tag = $tag;

        // global flag "disableLazyload" must be set on false
        $this->lazy = (bool)$lazy && self::$disableLazyload === false;

        // se non ho passato chiave di configurazione, uso quella tra le informazioni del record Gallery
        $this->configKey = $config ?? '';
        if (!$this->configKey && $image) {
            $this->configKey = Str::singular($image->item_table);
        }
    }

    /**
     * Get the view / contents that represent the component.
     *
     * @return \Illuminate\Contracts\View\View|\Closure|string
     */
    public function render()
    {
        $file = $this->image;

        if (!$file) {
            return '';
        }

        // recupera la configurazione di marvin per il file richiesto
        $config = config('marvin.functions.' . $this->configKey);
        // Costruisco srcset.
        // Ciclo le taglie impostate in configurazione, ma mando in output.
        // La dimensione reale del file, in modo che siano corrette se la configurazione
        // è stata aggiornata in seguito o se le immagini sono state caricate più piccole.
        $src = [];
        $srcset = [];
        $defaultSrc = null;
        $info = pathinfo($file->url);
        $dirname = ($info['dirname'] ?? '') . '/';
        $prefix = '';
        foreach ($config['size'] as $prefix => $size) {

            // tento di recuperare info sull'immagine, se fallisce, salto la taglia
            try {
                $getImageSize = getimagesize(Storage::disk("public")->path($dirname . $prefix . $info["basename"]));

                // lancio eccezione manualmente per gestire entrambe possibilità in unico punto
                if ($getImageSize === false) {
                    throw new Exception('Error getting image info []' . $dirname . $prefix . $info["basename"]);
                }
            } catch (Exception $e) {
                continue;
            }

            // memorizzo url di questa taglia
            $src[rtrim($prefix, '_')] = Storage::disk("public")->url($dirname . $prefix . $info["basename"]);

            // costruisco e memorizzo elemento del srcset con la larghezza reale dell'immagine
            $srcset[rtrim($prefix, '_')] = $src[rtrim($prefix, '_')] . ' ' . $getImageSize[0] . 'w';

            if (!$defaultSrc) {
                $defaultSrc = Storage::disk("public")->url($dirname . $prefix . $info["basename"]);
            }
        }

        // in caso di mancanza di taglie
        if (!$defaultSrc) {
            $defaultSrc = Storage::disk("public")->url($dirname . $prefix . $info["basename"]);
        }


        // classe extra
        $extraClass = '';
        if (array_key_exists('class', $this->extraAttributes)) {
            $extraClass = $this->extraAttributes['class'];
            unset($this->extraAttributes['class']);
        }

        // esplodo attributi extra
        $extraAttributes = [];
        foreach ($this->extraAttributes as $key => $value) {
            $extraAttributes[$key] = $key . '="' . $value . '"';
        }

        // recupero testo alternativo
        if ($file->current_lang->values && array_key_exists('alt_tag', $file->current_lang->values)) {
            $extraAttributes['alt'] = ' alt="'.$file->current_lang->values['alt_tag'].'"';
        }

        // se ho richiesto il lazy load
        if ($this->lazy === true) {
            // rimpiazzo attribuito sizes con data-sizes
            if (array_key_exists('sizes', $extraAttributes)) {
                $extraAttributes['sizes'] = str_replace('sizes', 'data-sizes', $extraAttributes['sizes']);
            }

            // img vs source
            switch ($this->tag):
                // in caso di "source" non ho classe lazy
                case 'source':
                    return '<source data-srcset="' . implode(',', $srcset) . '" ' . implode(' ', $extraAttributes) . '>';
                case 'img':
                    if (empty($src['P']) && empty($src['S'])) {
                        $src['S'] = $defaultSrc;
                    }
                    return '<img class="lazyload loading '.$extraClass.'"  src="' . ($src['P'] ?? $src['S']) . '"  data-srcset="' . implode(',', $srcset) . '" ' . implode(' ', $extraAttributes) . '>';
            endswitch;
        }

        // rimuovo la taglia placeholder dall'output senza lazy load
        if (array_key_exists('P', $srcset) && count($srcset) > 1) {
            unset($srcset['P']);
            $defaultSrc = current($srcset);
        }

        // output senza lazy load
        return '<' . $this->tag . ' src="' . $defaultSrc . '" srcset="' . implode(',', $srcset) . '" ' . implode(' ', $extraAttributes) . '>';
    }


    /**
     * Global hook to disable lazyload
     * (ignores "lazy" param in constructor)
     */
    public static function disableLazyload(): void
    {
        self::$disableLazyload = true;
    }
}

