<?php

namespace App\Providers;

use AtrioTeam\Lintilla\Localization\Router;
use Illuminate\Support\Facades\Request;
use Illuminate\Support\Facades\View;
use Illuminate\Support\ServiceProvider;

class ViewServiceProvider extends ServiceProvider
{
    /**
     * @var null|array<string, mixed>
     */
    protected null|array $viewData = null;

    /**
     * Register any application services.
     */
    public function register(): void
    {

    }

    /**
     * Bootstrap any application services.
     */
    public function boot(): void
    {

        /**
         * Inietto nome della route corrente,
         * priva del suffisso locale
         */
        View::composer('*', function ($view) {

            $view->active_route = null;

            // elaboro variabili solo la prima volta
            if ($this->viewData === null) {

                $this->viewData = [];

                // @phpstan-ignore ternary.alwaysTrue
                $routeName = Request::route() ? Request::route()->getName() : null;
                if ($routeName) {
                    $this->viewData["active_route"] =  $this->rightReplace($routeName, '_'.$this->app->getLocale(), '');
                }

                if (!isset($view->alternates) && !empty($this->viewData["active_route"])) {
                    $this->viewData["alternates"] = app(Router::class)->getAllAlternates($this->viewData["active_route"]);
                }

            }

            // inietto i dati in ogni view
            if ($this->viewData) {
                foreach ($this->viewData as $key => $value) {
                    $view->$key = $value;
                }
            }

        });

    }


    /**
     * Replace the last occurrence of a given value in the string.
     */
    private function rightReplace(string $string, string $search, string $replace): string
    {
        $offset = strrpos($string, $search);
        if ($offset !== false) {
            $length = strlen($search);
            $string = substr_replace($string, $replace, $offset, $length);
        }
        return $string;
    }
}

